    callWithPointer {
    uniffiRustCallWithError(SemesterCoreException) { _status ->
    UniffiLib.INSTANCE.uniffi_semester_core_fn_method_semesterdb_add_subject(
        it, FfiConverterTypeSubject.lower(`subject`),_status)
}
    }
    
    

    
