/**
 * @suppress
 */
public object FfiConverterTypeSemesterDb: FfiConverter<SemesterDb, Pointer> {

    override fun lower(value: SemesterDb): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): SemesterDb {
        return SemesterDb(value)
    }

    override fun read(buf: ByteBuffer): SemesterDb {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: SemesterDb) = 8UL

    override fun write(value: SemesterDb, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



