sealed class SemesterCoreException: kotlin.Exception() {
    
    class DatabaseException(
        
        val `message`: kotlin.String
        ) : SemesterCoreException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class ParseException(
        
        val `message`: kotlin.String
        ) : SemesterCoreException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class SyncException(
        
        val `message`: kotlin.String
        ) : SemesterCoreException() {
        override val message
            get() = "message=${ `message` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SemesterCoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): SemesterCoreException = FfiConverterTypeSemesterCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSemesterCoreError : FfiConverterRustBuffer<SemesterCoreException> {
    override fun read(buf: ByteBuffer): SemesterCoreException {
        

        return when(buf.getInt()) {
            1 -> SemesterCoreException.DatabaseException(
                FfiConverterString.read(buf),
                )
            2 -> SemesterCoreException.ParseException(
                FfiConverterString.read(buf),
                )
            3 -> SemesterCoreException.SyncException(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SemesterCoreException): ULong {
        return when(value) {
            is SemesterCoreException.DatabaseException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is SemesterCoreException.ParseException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is SemesterCoreException.SyncException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: SemesterCoreException, buf: ByteBuffer) {
        when(value) {
            is SemesterCoreException.DatabaseException -> {
                buf.putInt(1)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is SemesterCoreException.ParseException -> {
                buf.putInt(2)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is SemesterCoreException.SyncException -> {
                buf.putInt(3)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




